def descriptions(data):
    result={}
    for group,lines in TEXT.items():
        focuses=[n for n in data['nodes'] if n['group']==group]
        assert len(focuses)==len(lines),(group,len(focuses),len(lines))
        result.update({n['id']:line for n,line in zip(focuses,lines)})
    assert len(result)==len(data['nodes'])
    return result
